//! Excluded actual-gallery external work order preview and bounded native DOM replay.
use dioxus::prelude::*;
use dioxus_ix::*;

#[path = "../../examples/gallery/external_work_order.rs"]
mod gallery_work_order;

#[component]
pub fn ExternalWorkOrderPreview() -> Element {
    let mut narrow = use_signal(|| false);
    #[cfg(all(feature = "desktop", not(target_arch = "wasm32")))]
    let window = dioxus::desktop::window();
    rsx! {
        style { {STYLES} }
        style { {gallery_work_order::STYLES} }
        IxTheme { class: "external-work-order-review",
            h1 { "External work order" }
            Button { id: "external-work-order-narrow", variant: ButtonVariant::Secondary,
                onclick: move |_| narrow.toggle(), if narrow() { "Use wide preview" } else { "Use narrow preview" }
            }
            div { id: "external-work-order-frame", style: if narrow() { "width:340px;max-width:100%;min-width:0" } else { "width:960px;max-width:100%;min-width:0" },
                gallery_work_order::ExternalWorkOrderExample {}
            }
            div { onmounted: move |_| {
                #[cfg(all(feature = "desktop", not(target_arch = "wasm32")))]
                {
                    let window = window.clone();
                    spawn(async move {
                        let query = crate::dom_query::eval(NATIVE_EXTERNAL_WORK_ORDER_CHECK);
                        if let Err(error) = query.send("externalforms") {
                            eprintln!("External work order native driver failed to start: {error:?}");
                            std::process::exit(1);
                        }
                        match query.join::<serde_json::Value>().await {
                            Ok(result) if result["ok"] == true => {
                                println!("Dioxus native external work order: {result}");
                                window.close();
                            }
                            result => {
                                eprintln!("Dioxus native external work order failed: {result:?}");
                                std::process::exit(1);
                            }
                        }
                    });
                    spawn(async move {
                        futures_timer::Delay::new(std::time::Duration::from_secs(30)).await;
                        eprintln!("External work order native driver timed out");
                        std::process::exit(1);
                    });
                }
            } }
        }
    }
}

const STYLES: &str = "body{margin:0}.external-work-order-review{box-sizing:border-box;min-height:100vh;padding:24px}.external-work-order-review>h1{font-size:28px;margin:0 0 24px}.external-work-order-review h2{font-size:22px;margin:24px 0 16px}.external-work-order-review p{max-width:72ch;line-height:1.5}#external-work-order-frame{margin-top:24px}@media(max-width:600px){.external-work-order-review{padding:16px}}";

